SELECT id, user_id, original_filename, name, phone, email, gender, age, skills, education, work_experience, status, created_at FROM resumes WHERE status = 2
AND ( skills LIKE CONCAT('%', #{keyword}, '%') OR raw_text LIKE CONCAT('%', #{keyword}, '%') OR parse_result LIKE CONCAT('%', #{keyword}, '%') OR name LIKE CONCAT('%', #{keyword}, '%') OR phone LIKE CONCAT('%', #{keyword}, '%') OR email LIKE CONCAT('%', #{keyword}, '%') OR education LIKE CONCAT('%', #{keyword}, '%') OR work_experience LIKE CONCAT('%', #{keyword}, '%') )
AND gender = #{gender}
AND age >= #{minAge}
AND age <= #{maxAge}
ORDER BY
age
created_at
ASC DESC
LIMIT #{offset}, #{pageSize}

SELECT COUNT(*) FROM resumes WHERE status = 2
AND ( skills LIKE CONCAT('%', #{keyword}, '%') OR raw_text LIKE CONCAT('%', #{keyword}, '%') OR parse_result LIKE CONCAT('%', #{keyword}, '%') OR name LIKE CONCAT('%', #{keyword}, '%') OR phone LIKE CONCAT('%', #{keyword}, '%') OR email LIKE CONCAT('%', #{keyword}, '%') OR education LIKE CONCAT('%', #{keyword}, '%') OR work_experience LIKE CONCAT('%', #{keyword}, '%') )
AND gender = #{gender}
AND age >= #{minAge}
AND age <= #{maxAge}
